import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class SummaryServletCoverageTest {

	@TempDir
	File tempDir;

	@Test
	void serviceRendersTheRepositoryWithoutCountingIt() throws Exception {
		SummaryServlet servlet = new SummaryServlet();
		Repository repository = mock(Repository.class);
		RepositoryManager manager = mock(RepositoryManager.class);
		RepositoryInfo info = new RepositoryInfo();
		info.setId("memory");
		info.setDescription("Memory repo");
		TupleResultBuilder builder = mock(TupleResultBuilder.class);

		servlet.setRepository(repository);
		servlet.setRepositoryManager(manager);
		servlet.setRepositoryInfo(info);

		servlet.service(builder);

		// The counts are requested separately (plan task M13.3), so the page never opens a connection.
		verify(builder).result(eq("memory"), eq("Memory repo"), isNull(), isNull(), isNull(), isNull());
		verify(builder).end();
		verify(repository, never()).getConnection();
	}

	@Test
	void getServerReturnsLocalRemoteAndGracefullyIgnoresOtherManagers() {
		SummaryServlet servlet = new SummaryServlet();

		servlet.setRepositoryManager(new LocalRepositoryManager(tempDir));
		assertThat(invokeGetServer(servlet)).isEqualTo(tempDir.toString());

		RemoteRepositoryManager remoteManager = mock(RemoteRepositoryManager.class);
		when(remoteManager.getServerURL()).thenReturn("https://remote.example/rdf4j-server");
		servlet.setRepositoryManager(remoteManager);
		assertThat(invokeGetServer(servlet)).isEqualTo("https://remote.example/rdf4j-server");

		servlet.setRepositoryManager(mock(RepositoryManager.class));
		assertThat(invokeGetServer(servlet)).isNull();
	}

	@Test
	void getEffectiveConfigTurtleReturnsNullWhenUnavailableOrOnManagerFailure() {
		SummaryServlet servlet = new SummaryServlet();
		assertThat(invokeGetEffectiveConfigTurtle(servlet)).isNull();

		RepositoryManager manager = mock(RepositoryManager.class);
		servlet.setRepositoryManager(manager);
		servlet.setRepositoryInfo(null);
		assertThat(invokeGetEffectiveConfigTurtle(servlet)).isNull();

		servlet.setRepositoryManager(manager);
		servlet.setRepositoryInfo(new RepositoryInfo());
		assertThat(invokeGetEffectiveConfigTurtle(servlet)).isNull();

		RepositoryInfo info = new RepositoryInfo();
		info.setId("memory");
		servlet.setRepositoryManager(manager);
		servlet.setRepositoryInfo(info);
		assertThat(invokeGetEffectiveConfigTurtle(servlet)).isNull();

		when(manager.getRepositoryConfig("memory")).thenThrow(new RepositoryException("boom"));
		assertThat(invokeGetEffectiveConfigTurtle(servlet)).isNull();

		RepositoryManager configFailureManager = mock(RepositoryManager.class);
		when(configFailureManager.getRepositoryConfig("memory")).thenThrow(new RepositoryConfigException("broken"));
		servlet.setRepositoryManager(configFailureManager);
		assertThat(invokeGetEffectiveConfigTurtle(servlet)).isNull();
	}

	private static String invokeGetServer(SummaryServlet servlet) {
		return (String) invoke(servlet, "getServer", new Class<?>[0]);
	}

	private static String invokeGetEffectiveConfigTurtle(SummaryServlet servlet) {
		return (String) invoke(servlet, "getEffectiveConfigTurtle", new Class<?>[0]);
	}

	private static Object invoke(Object target, String methodName, Class<?>[] parameterTypes, Object... args) {
		try {
			Method method = target.getClass().getDeclaredMethod(methodName, parameterTypes);
			method.setAccessible(true);
			return method.invoke(target, args);
		} catch (ReflectiveOperationException e) {
			throw new AssertionError("Could not invoke " + methodName, e);
		}
	}
}
